"use client";

import { useEffect, useMemo, useRef, useState } from "react";
import { useCrate } from "@/components/agent-wait-states/crate-provider";
import type { AgentSource, AgentStatus, AgentStatusSnapshot } from "@/components/agent-wait-states/types";

type UnknownPart = {
  type?: string;
  text?: string;
  state?: string;
  toolName?: string;
  url?: string;
  title?: string;
  sourceId?: string;
  filename?: string;
  toolInvocation?: { toolName?: string; state?: string };
};

type ChatLike = {
  status: "submitted" | "streaming" | "ready" | "error" | string;
  messages: Array<{ role?: string; parts?: UnknownPart[]; content?: string }>;
  error?: unknown;
  stop?: () => void;
};

export type UseAgentStatusOptions = { manualStatus?: AgentStatus; onCancel?: () => void; stallAfterMs?: number };

const FINISHED_TOOL_STATES = new Set(["output-available", "output-error", "result", "error"]);

function readTool(part: UnknownPart) {
  const type = part.type ?? "";
  const invocation = part.toolInvocation;
  const name = part.toolName ?? invocation?.toolName ?? (type.startsWith("tool-") ? type.slice(5) : undefined);
  const state = part.state ?? invocation?.state;
  const isTool = type === "dynamic-tool" || type === "tool-invocation" || type.startsWith("tool-");
  return isTool && name && !FINISHED_TOOL_STATES.has(state ?? "") ? name : undefined;
}

function inspectMessages(messages: ChatLike["messages"], sourceTitle: string) {
  let activeToolName: string | undefined;
  let content = "";
  let reasoning = "";
  let latestPart: "text" | "reasoning" | "source" | "other" = "other";
  const sources: AgentSource[] = [];

  for (const message of messages) {
    if (message.content) content += message.content;
    for (const part of message.parts ?? []) {
      const type = part.type ?? "";
      if (type === "text" && part.text) { content += part.text; latestPart = "text"; }
      if (type === "reasoning" || type === "reasoning-text") {
        reasoning += part.text ?? "";
        latestPart = "reasoning";
      }
      if (type === "source-url" || type === "source-document" || type === "source") {
        sources.push({
          id: part.sourceId,
          url: part.url,
          title: part.title ?? part.filename ?? part.url ?? sourceTitle,
        });
        latestPart = "source";
      }
      const toolName = readTool(part);
      if (toolName) { activeToolName = toolName; latestPart = "other"; }
    }
  }

  return {
    activeToolName,
    reasoning,
    sources,
    latestPart,
    contentSignature: `${content.length}:${content.slice(-80)}:${reasoning.length}:${sources.length}`,
  };
}

export function useAgentStatus(chat: ChatLike, options: UseAgentStatusOptions = {}): AgentStatusSnapshot {
  const { labels } = useCrate();
  const inspected = useMemo(() => inspectMessages(chat.messages, labels.sourceTitle), [chat.messages, labels.sourceTitle]);
  const [now, setNow] = useState(() => Date.now());
  const busySince = useRef<number | null>(null);
  const lastContentAt = useRef(Date.now());
  const previousSignature = useRef(inspected.contentSignature);
  const busy = chat.status === "submitted" || chat.status === "streaming";

  useEffect(() => {
    if (busy && busySince.current === null) busySince.current = Date.now();
    if (!busy) busySince.current = null;
  }, [busy]);

  useEffect(() => {
    if (inspected.contentSignature !== previousSignature.current) {
      previousSignature.current = inspected.contentSignature;
      lastContentAt.current = Date.now();
      setNow(Date.now());
    }
  }, [inspected.contentSignature]);

  useEffect(() => {
    if (!busy) return;
    const timer = window.setInterval(() => setNow(Date.now()), 250);
    return () => window.clearInterval(timer);
  }, [busy]);

  const elapsedMs = busySince.current ? Math.max(0, now - busySince.current) : 0;
  const stalled = chat.status === "streaming" && now - lastContentAt.current >= (options.stallAfterMs ?? 5000);

  let state: AgentStatus;
  if (options.manualStatus) state = options.manualStatus;
  else if (chat.status === "error" || chat.error) state = "error";
  else if (stalled) state = "stalled";
  else if (inspected.activeToolName && busy) state = "tool";
  else if (chat.status === "streaming" && inspected.latestPart === "reasoning") state = "reasoning";
  else if (chat.status === "streaming" && inspected.latestPart === "source") state = "sources";
  else if (chat.status === "streaming") state = "streaming";
  else if (chat.status === "submitted") state = "thinking";
  else state = "done";

  const label = elapsedMs >= 8000 ? labels.stillThinking : labels.thinking;
  const cancel = options.onCancel ?? chat.stop;

  return {
    state,
    activeToolName: inspected.activeToolName,
    reasoning: inspected.reasoning || undefined,
    sources: inspected.sources,
    elapsedMs,
    showCancel: elapsedMs >= 20000 && Boolean(cancel),
    label,
    cancel,
  };
}

"use client";

import { createContext, useContext, useMemo } from "react";

/** Locale-aware helpers passed to every label that contains a number. */
export type CrateFormat = {
  locale: string;
  /** 1234 -> "1,234" (en) or "1 234" (fr). */
  number: (value: number) => string;
  /** 30 -> "30s" in en. Other locales use their own short unit format. */
  seconds: (value: number) => string;
  /** Picks a form by Intl plural rules, e.g. plural(n, { one: "source", other: "sources" }). */
  plural: (value: number, forms: Partial<Record<Intl.LDMLPluralRule, string>> & { other: string }) => string;
};

export type CrateLabels = {
  thinking: string;
  stillThinking: string;
  cancel: string;
  responseStreaming: string;
  toolActivity: string;
  runningTool: (toolName: string) => string;
  stalled: string;
  error: string;
  retry: string;
  done: string;
  showThinking: string;
  thoughtFor: (seconds: number, format: CrateFormat) => string;
  reasoningPlaceholder: string;
  sources: string;
  sourceFallback: string;
  sourceTitle: string;
  moreSources: (count: number, format: CrateFormat) => string;
  plan: string;
  planProgress: (current: number, total: number, format: CrateFormat) => string;
  approvalRequired: string;
  approvalTitle: string;
  approvalPreview: string;
  expiresIn: (seconds: number, format: CrateFormat) => string;
  deny: string;
  allow: string;
  queuePosition: (position: number, format: CrateFormat) => string;
  rateLimited: (seconds: number, format: CrateFormat) => string;
  fileUploading: string;
  fileReading: string;
  fileChunking: string;
  fileReady: string;
  fileProgress: (percent: number, format: CrateFormat) => string;
};

export const defaultLabels: CrateLabels = {
  thinking: "Thinking…",
  stillThinking: "Still thinking…",
  cancel: "Cancel",
  responseStreaming: "Response streaming",
  toolActivity: "Agent tool activity",
  runningTool: (toolName) => `Running ${toolName}…`,
  stalled: "Still working…",
  error: "Something went wrong.",
  retry: "Retry",
  done: "Done",
  showThinking: "Show thinking",
  thoughtFor: (seconds, f) => `Thought for ${f.seconds(seconds)}`,
  reasoningPlaceholder: "Working through the details…",
  sources: "Sources",
  sourceFallback: "source",
  sourceTitle: "Source",
  moreSources: (count, f) => `+${f.number(count)} more`,
  plan: "Plan",
  planProgress: (current, total, f) => `${f.number(current)} of ${f.number(total)}`,
  approvalRequired: "Approval required",
  approvalTitle: "The agent wants to send this email",
  approvalPreview: "Review this action before it runs.",
  expiresIn: (seconds, f) => `Expires in ${f.seconds(seconds)}`,
  deny: "Deny",
  allow: "Allow",
  queuePosition: (position, f) => `You’re #${f.number(position)} in line`,
  rateLimited: (seconds, f) => `Slow down. Try again in ${f.seconds(seconds)}`,
  fileUploading: "Upload",
  fileReading: "Reading",
  fileChunking: "Chunking",
  fileReady: "Ready",
  fileProgress: (percent, f) => `${f.number(percent)}%`,
};

export function createFormat(locale: string): CrateFormat {
  const number = new Intl.NumberFormat(locale);
  const seconds = new Intl.NumberFormat(locale, { style: "unit", unit: "second", unitDisplay: "narrow" });
  const plural = new Intl.PluralRules(locale);
  return {
    locale,
    number: (value) => number.format(value),
    seconds: (value) => seconds.format(value),
    plural: (value, forms) => forms[plural.select(value)] ?? forms.other,
  };
}

type CrateContextValue = { labels: CrateLabels; format: CrateFormat };

const CrateContext = createContext<CrateContextValue>({ labels: defaultLabels, format: createFormat("en") });

export type CrateProviderProps = {
  /** Any labels to replace. Missing ones fall back to English. */
  labels?: Partial<CrateLabels>;
  /** BCP 47 locale for numbers, times, and plurals, e.g. "fr" or "ar-EG". Inherited when omitted. */
  locale?: string;
  children: React.ReactNode;
};

/** Sets labels and locale for every crate component inside it. Renders no element. */
export function CrateProvider({ labels, locale, children }: CrateProviderProps) {
  const parent = useContext(CrateContext);
  const resolvedLocale = locale ?? parent.format.locale;
  const value = useMemo(
    () => ({
      labels: { ...parent.labels, ...labels },
      format: resolvedLocale === parent.format.locale ? parent.format : createFormat(resolvedLocale),
    }),
    [parent, labels, resolvedLocale],
  );
  return <CrateContext.Provider value={value}>{children}</CrateContext.Provider>;
}

/** Labels and format for a component: provider values, overridden by the component's own labels prop. */
export function useCrate(overrides?: Partial<CrateLabels>): CrateContextValue {
  const context = useContext(CrateContext);
  return useMemo(
    () => (overrides ? { labels: { ...context.labels, ...overrides }, format: context.format } : context),
    [context, overrides],
  );
}

import type { CrateLabels } from "./crate-provider";

export type AgentStatus =
  | "thinking"
  | "reasoning"
  | "sources"
  | "tool"
  | "plan"
  | "approval"
  | "queue"
  | "file"
  | "streaming"
  | "stalled"
  | "error"
  | "done";

export type AgentSource = {
  id?: string;
  url?: string;
  domain?: string;
  title: string;
};

export type AgentStatusSnapshot = {
  state: AgentStatus;
  activeToolName?: string;
  reasoning?: string;
  sources: AgentSource[];
  elapsedMs: number;
  showCancel: boolean;
  label: string;
  cancel?: () => void;
};

export type WaitStateProps = {
  className?: string;
  accent?: boolean;
  /** Replace any of this component's labels. Overrides CrateProvider. */
  labels?: Partial<CrateLabels>;
};

export function cx(...values: Array<string | false | null | undefined>) {
  return values.filter(Boolean).join(" ");
}
